import { useState } from "react";

type Ticket = { id: string; customer: string };

function ReplyBox({ ticket }: { ticket: Ticket }) {
  const [draft, setDraft] = useState("");
  return (
    <>
      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button onClick={() => sendReply(ticket.id, draft)}>
        Reply to {ticket.customer}
      </button>
    </>
  );
}

export function TicketPage({ ticket }: { ticket: Ticket }) {
  // Same type at the same position: Bob's ticket keeps Alice's draft
  return <ReplyBox ticket={ticket} />;
}

