import { useState } from "react";

type Drafts = Record<string, string>;

export function ReplyPanel({ ticketId }: { ticketId: string }) {
  // No key on purpose: the panel keeps its position, so the map survives
  const [drafts, setDrafts] = useState<Drafts>({});
  const draft = drafts[ticketId] ?? "";
  return (
    <textarea
      value={draft}
      onChange={(e) => setDrafts({ ...drafts, [ticketId]: e.target.value })}
    />
  );
}
